import logging
import re
import time
import taf.rfrl.utilities.logger.custom_logger as logger
from taf.internal.robot_typecasts import time_to_seconds
from taf.rfrl.bts.devices.exceptions import InvalidParameterValue, IncorrectStatuses, CellNotOnAir
from taf.rfrl.bts.devices.du.alarm_verification import GnbAlarmVerification, EnbAlarmVerification
from taf.rfrl.bts.devices.du.cell_operations import GnbCellOperations, EnbCellOperations
from taf.rfrl.bts.devices.du.commissioning import GnbCommissioning, EnbCommissioning
from taf.rfrl.bts.devices.du.du_operations import GnbDuOperations, EnbDuOperations
from taf.rfrl.procedures.resources.python.cable import GnbCable, EnbCable


class SFP:
    """Base keywords for eNB and gNB"""

    def __init__(self, bts_type='GNB'):
        """
        Constructor of SFP class.
        """
        self.bts_du_obj = GnbDuOperations() if bts_type == 'GNB' else EnbDuOperations()
        self.bts_scf_obj = GnbCommissioning() if bts_type == 'GNB' else EnbCommissioning()
        self.bts_alarm_obj = GnbAlarmVerification() if bts_type == 'GNB' else EnbAlarmVerification()
        self.bts_cell_obj = GnbCellOperations() if bts_type == 'GNB' else EnbCellOperations()
        self.cablink = GnbCable() if self.bts_type == 'GNB' else EnbCable()
        self.bts_type = bts_type
        self.additional_allowed_alarms = []

    def lock_sfp(self, dist_name, bts_id=0):
        """
        Lock SFP
        :param dist_name: lane distName
        :param bts_id: BTS id, default 0
        :return: None
        """
        adjusted_dist_name = self.bts_du_obj.adjust_dist_name(dist_name=dist_name, bts_id=bts_id)
        self.bts_scf_obj.perform_configuration_parameter_recommissioning(
            dist_name=adjusted_dist_name, parameter='administrativeState', value='Locked', operation='update',
            bts_id=bts_id, skip_parameter_relation_errors=False, should_activate=True, timeout=60)

    def unlock_sfp(self, dist_name, bts_id=0):
        """
        Unlock SFP
        :param dist_name: lane distName
        :param bts_id: BTS id, default 0
        :return: None
        """
        adjusted_dist_name = self.bts_du_obj.adjust_dist_name(dist_name=dist_name, bts_id=bts_id)
        self.bts_scf_obj.perform_configuration_parameter_recommissioning(
            dist_name=adjusted_dist_name, parameter='administrativeState', value='Unlocked', operation='update',
            bts_id=bts_id, skip_parameter_relation_errors=False, should_activate=True, timeout=60)

    def lock_sfp_with_alarm_verification(self, sfp_lock_record, bts_id=0, du_id=0):
        """
        Lock SFP and verify alarm and cell status afterward
        :param sfp_lock_record: tuple/list in format:
            {
                'lane_dist_name': 'MRBTS-{}/EQM-1/APEQM-1/CABINET-1/BBMOD-1/SFP-1LANE-1',   # mandatory
                'cells_affected_by_alarms': [1, 2, 3, 4],                                   # mandatory
                'need_unlock_to_on_air': False,                                             # optional
                'timeout_for_cells_initialization': '20 min',                               # optional
                'timeout_for_cells_to_be_on_air': '6min'                                    # optional
                'reset_site_after_lane_locking': 'False'                                    # optional
                'time_for_site_available': '600'                                            # optional
            }
        :param bts_id: BTS id, default 0
        :param du_id: DU id, default 0
        :return: None
        """
        lane_dist_name = sfp_lock_record['lane_dist_name']
        adjusted_lane_dist_name = self.bts_du_obj.adjust_dist_name(dist_name=lane_dist_name, bts_id=bts_id)
        lane_link_mode = self.get_sfp_link_mode(lane_dist_name=adjusted_lane_dist_name, bts_id=bts_id)
        logger.log_info_to_console(f'Start locking of lane: {adjusted_lane_dist_name}')
        logger.log_info_to_console(f'Lane mode: {lane_link_mode}', log_hierarchy=3)
        self.additional_allowed_alarms.append('Not able to synchronize baseband bus')
        alarm_affecting_cells = self._get_proper_alarm_affecting_cells(lane_link_mode=lane_link_mode)
        if alarm_affecting_cells:
            self.additional_allowed_alarms.append(alarm_affecting_cells['fault_name'])
        if self.bts_alarm_obj.alarms_watcher:
            self.bts_alarm_obj.allow_alarm(alarm=self.additional_allowed_alarms, bts_id=bts_id)
            logging.info(f'Alarms added to allowed: {self.additional_allowed_alarms}')
        self.lock_sfp(dist_name=lane_dist_name, bts_id=bts_id)
        self.verify_rf_port_status_for_specific_lane(lane_dist_name=adjusted_lane_dist_name, status='disable',
                                                     bts_id=bts_id)
        logger.log_info_to_console(f'Lane {adjusted_lane_dist_name} is locked')
        cells_affected_by_alarms = sfp_lock_record['cells_affected_by_alarms']
        if lane_link_mode["synchronization"] or lane_link_mode["configuration"]:
            self.bts_alarm_obj.wait_for_alarm_activation(fault_id=alarm_affecting_cells['fault_id'], awaiting_time=120,
                                                         bts_id=bts_id)
            logger.log_info_to_console(f"Alarm `{alarm_affecting_cells['fault_name']}` is active")
            logger.log_info_to_console('Verifying cells affected by alarms on impacted cells')
            self.verify_cells_affected_by_alarm(cells=cells_affected_by_alarms,
                                                fault_id=alarm_affecting_cells['fault_id'], bts_id=bts_id)
        if sfp_lock_record['reset_site_after_lane_locking']:
            logger.log_info_to_console('Resetting site')
            self.bts_du_obj.reset_bts(bts_id=bts_id)
            logger.log_info_to_console('Waiting for site availability')
            self.bts_du_obj.wait_for_site_to_be_available(bts_id=bts_id,
                                                          timeout=int(sfp_lock_record['time_for_site_available']),
                                                          interval=30)
            cells_affected_by_alarms = self.bts_cell_obj.get_all_global_cell_ids(bts_id=bts_id)
        if lane_link_mode["synchronization"] or lane_link_mode["configuration"] \
                or sfp_lock_record['reset_site_after_lane_locking']:
            logger.log_info_to_console(f'Waiting for cells initialization {cells_affected_by_alarms}')
            for cell in cells_affected_by_alarms:
                self._wait_for_cell_initialization_end(cell_id=cell,
                                                       bts_id=bts_id,
                                                       timeout=sfp_lock_record['timeout_for_cells_initialization'])
            logger.log_info_to_console(f'Cells {cells_affected_by_alarms} were initialized')
            if not sfp_lock_record['need_unlock_to_on_air']:
                logging.info('Waiting for all cells to be onAir')
                self.bts_cell_obj.wait_for_all_cells_to_be_onair(bts_id=bts_id,
                                                                 timeout=sfp_lock_record['timeout_for_cells_to_be_on_air'],
                                                                 interval=30)
        self.bts_cell_obj.verify_all_cells_are_onair(bts_id=bts_id)
        logger.log_info_to_console('All cells are onAir')
        if not sfp_lock_record['reset_site_after_lane_locking']:
            logger.log_info_to_console('Waiting for alarm `Not able to synchronize baseband bus` activation')
            self.bts_alarm_obj.wait_for_alarm_activation(fault_id=1815, awaiting_time=600, bts_id=bts_id)
            logger.log_info_to_console('Alarm `Not able to synchronize baseband bus` is activated\n')

    def unlock_sfp_with_alarm_verification(self, sfp_unlock_record, bts_id=0, du_id=0):
        """
        Unlock SFP and verify alarm and cell status afterward
        :param sfp_unlock_record: tuple/list in format:
            {
                'lane_dist_name': 'MRBTS-{}/EQM-1/APEQM-1/CABINET-1/BBMOD-1/SFP-1LANE-1',   # mandatory
                'cells_affected_by_alarms': [1, 2, 3, 4],                                   # mandatory
                'need_unlock_to_on_air': False,                                             # optional
                'timeout_for_cells_initialization': '20 min',                               # optional
                'timeout_for_cells_to_be_on_air': '6min'                                    # optional
                'reset_site_after_lane_locking': 'False'                                    # optional
                'time_for_site_available': '600'                                            # optional
            }
        :param bts_id: BTS id, default 0
        :param du_id: DU id, default 0
        :return: None
        """
        lane_dist_name = sfp_unlock_record['lane_dist_name']
        adjusted_lane_dist_name = self.bts_du_obj.adjust_dist_name(dist_name=lane_dist_name, bts_id=bts_id)
        logger.log_info_to_console(f'Start unlocking of obj: {adjusted_lane_dist_name}')
        self.unlock_sfp(dist_name=lane_dist_name, bts_id=bts_id)
        self.verify_rf_port_status_for_specific_lane(lane_dist_name=adjusted_lane_dist_name, status='enable',
                                                     bts_id=bts_id)
        logger.log_info_to_console(f'{adjusted_lane_dist_name} is unlocked')
        if not sfp_unlock_record['reset_site_after_lane_locking']:
            logger.log_info_to_console('Waiting for alarm `Not able to synchronize baseband bus` deactivation')
            self.bts_alarm_obj.wait_for_alarm_deactivation(fault_id=1815, awaiting_time=600, bts_id=bts_id)
            logger.log_info_to_console('Alarm `Not able to synchronize baseband bus` is deactivated')
        if sfp_unlock_record['need_unlock_to_on_air']:
            try:
                logging.info('Waiting for all cells to be onAir')
                self.bts_cell_obj.wait_for_all_cells_to_be_onair(
                    bts_id=bts_id, timeout=sfp_unlock_record['timeout_for_cells_to_be_on_air'], interval=30)
            except CellNotOnAir as e:
                logging.warning(e)
                logging.warning("Doing additional site reset because cell hasn't recovered after SFP unlock "
                                "(refer to PR729516/PR748050)")
                self.bts_du_obj.reset_bts(bts_id=bts_id)
                self.bts_cell_obj.wait_for_all_cells_to_be_onair(
                    bts_id=bts_id, timeout=sfp_unlock_record['timeout_for_cells_to_be_on_air'], interval=30)
        self.bts_cell_obj.verify_all_cells_are_onair(bts_id=bts_id)
        logger.log_info_to_console('All cells are onAir\n')
        if self.additional_allowed_alarms and self.bts_alarm_obj.alarms_watcher:
            time.sleep(10)
            self.bts_alarm_obj.disallow_alarm(alarm=self.additional_allowed_alarms, bts_id=bts_id)
            logging.info(f'Alarms removed from allowed: {self.additional_allowed_alarms}')
        self.additional_allowed_alarms.clear()

    def get_sfp_config(self, bts_id=0, du_id=0):
        """
        Get SFP config
        :param bts_id: BTS id, default 0
        :param du_id: DU id, default 0
        :return: SFP config, example
            {
                "MRBTS-76220/EQM-1/APEQM-1/CABINET-1/BBMOD-1":[
                    {
                        "sfp_id":"SFP-1",
                        "rf_port":"RF1",
                        "runtime":"MRBTS-76220/EQM_R-1/APEQM_R-1/CABINET_R-1/BBMOD_R-1/SFP_R-1"
                    }
                ]
            }
        """
        bts_info = self.bts_du_obj.get_bts_info(bts_id=bts_id, du_id=du_id)
        sfp_config = {}
        modules = ['basebandModules', 'systemModules']
        pattern = re.compile(r'(?P<bbmod_id>.+/(BBMOD|SMOD)-\d+)/(?P<sfp_id>SFP-\d+)')
        for module_type in modules:
            for bbmod in bts_info[module_type]:
                ports_info = bbmod['ports']
                for port in ports_info:
                    logging.debug(f"RF port (SFP ID) for {port['id'].get('configuration', port['id']['runtime'])}:"
                                  f" {port['label']}")
                    matched = pattern.match(port['id'].get('configuration', port['id']['runtime']))
                    if matched:
                        bbmod_id = matched.group('bbmod_id')
                        if bbmod_id not in sfp_config.keys():
                            sfp_config[bbmod_id] = []
                        sfp_config[bbmod_id].append({
                            'sfp_id': matched.group('sfp_id'),
                            'rf_port': port['label'],
                            'runtime': port['id']['runtime']
                        })
        logging.info(f'SFP_CONFIG: {sfp_config}')
        return sfp_config

    def verify_rf_port_status_for_specific_lane(self, lane_dist_name, status='enable', bts_id=0):
        """
        Verify RF port status for specific lane
        :param lane_dist_name: lane distName
        :param status: RF port status, default enable
        :param bts_id: BTS id, default 0
        :return: None
        """
        adjusted_lane_dist_name = self.bts_du_obj.adjust_dist_name(dist_name=lane_dist_name, bts_id=bts_id)
        mod_dist_name, sfp_id, lane = self.verify_lane_dist_name_format(lane_dist_name=adjusted_lane_dist_name)
        sfps_config = self.get_sfp_config(bts_id=bts_id)
        rf_port_runtime_dist_name = None
        if mod_dist_name in sfps_config.keys():
            for item in sfps_config[mod_dist_name]:
                if item['sfp_id'] == sfp_id:
                    rf_port_runtime_dist_name = item['runtime']
                    break
        if rf_port_runtime_dist_name:
            param_dict = self.create_dict_with_parameter_to_verify(dist_name=rf_port_runtime_dist_name,
                                                                   parameter='operationalState',
                                                                   value=status.lower(),
                                                                   adjust_dist_name=False)
            self.bts_du_obj.verify_configuration_parameters_values(param_dict=param_dict, bts_id=bts_id)
        else:
            raise InvalidParameterValue(f'No RF port dist_name found for `{adjusted_lane_dist_name}`')

    def get_sfp_link_mode(self, lane_dist_name, bts_id=0):
        """
        Get SFP link mode
        :param lane_dist_name: lane distName
        :param bts_id: BTS id, default 0
        :return: SFP link mode, example
            {
                'configuration': True,
                'data': True,
                'synchronization': True,
                'dc': False
            }
        """
        mod_dist_name, sfp_id, lane = self.verify_lane_dist_name_format(lane_dist_name=lane_dist_name)
        cablinks_link_mode = self.cablink.get_cablinks_link_mode(bts_id=bts_id)
        sfps_link_mode = self.get_sfp_config(bts_id=bts_id)
        sfps_for_mod = sfps_link_mode.get(mod_dist_name, None)
        rf_port = None
        if sfps_for_mod:
            for sfp in sfps_for_mod:
                if sfp['sfp_id'] == sfp_id:
                    rf_port = sfp['rf_port']
                    break
        else:
            raise Exception(f'No SPFs for {mod_dist_name} found.')
        if not rf_port:
            raise Exception(f'No RF port for {mod_dist_name} found.')
        cablinks_for_mod = cablinks_link_mode.get(mod_dist_name, None)
        if cablinks_for_mod:
            for cablink in cablinks_for_mod:
                if cablink['rf_port'] == rf_port:
                    return cablink['link_mode']
        else:
            raise Exception(f'No CABLINKs for {mod_dist_name} found.')
        return

    def verify_sfp_record_data(self, sfp_record, bts_id=0):
        """
        Verify if sfp_record contain all need parameters and add default optional parameters if needed
        :param sfp_record: tuple/list in format:
            {
                'lane_dist_name': 'MRBTS-{}/EQM-1/APEQM-1/CABINET-1/BBMOD-1/SFP-1LANE-1',   # mandatory
                'cells_affected_by_alarms': [1, 2, 3, 4],                                   # mandatory
                'need_unlock_to_on_air': False,                                             # optional
                'timeout_for_cells_initialization': '20 min',                               # optional
                'timeout_for_cells_to_be_on_air': '6min'                                    # optional
                'reset_site_after_lane_locking': 'False'                                    # optional
                'time_for_site_available': '600'                                            # optional
            }
        :param bts_id: BTS id, default 0
        :return: sfp record with all needed parameters
        """
        message = ""
        if 'lane_dist_name' not in sfp_record or not sfp_record['lane_dist_name']:
            message += '`lane_dist_name` not specify or is empty in `sfp_record` data\n'
        elif not self.bts_scf_obj.get_parameters_by_dist_name(dist_name=sfp_record['lane_dist_name'], bts_id=bts_id):
            message += 'Verify if dist_name `{}` specified in `sfp_record` exists in BTS\n'.format(sfp_record['lane_dist_name'])
        if 'cells_affected_by_alarms' not in sfp_record or not sfp_record['cells_affected_by_alarms']:
            message += '`cells_affected_by_alarms` not specify or is empty in `sfp_record` data\n'
        if message:
            raise Exception(message)
        if 'need_unlock_to_on_air' not in sfp_record:
            sfp_record.update({'need_unlock_to_on_air': False})
        if 'timeout_for_cells_initialization' not in sfp_record:
            sfp_record.update({'timeout_for_cells_initialization': '20 min'})
        if 'timeout_for_cells_to_be_on_air' not in sfp_record:
            sfp_record.update({'timeout_for_cells_to_be_on_air': '6 min'})
        if 'reset_site_after_lane_locking' not in sfp_record:
            sfp_record.update({'reset_site_after_lane_locking': False})
        if 'time_for_site_available' not in sfp_record:
            sfp_record.update({'time_for_site_available': '600'})
        return sfp_record

    def verify_cells_affected_by_alarm(self, cells, fault_id, bts_id=0):
        """
        Check if expected cells are affected by specific alarm
        :param cells: expected cells affected by specific alarm
        :param fault_id: alarm fault id affecting cells
        :param bts_id: BTS id, default 0
        :return: None
        """
        affected_cells = list()
        affected_cells = self._get_all_affected_cells_by_fid(fault_id=fault_id, bts_id=bts_id)
        cells = set(sorted(map(int, cells)))
        if cells != affected_cells:
            raise Exception(f'Affected cells={affected_cells} != expected affected cells={cells}')
        else:
            logger.log_info_to_console(f'Cells {set(affected_cells)} affected as expected')

    def _get_all_affected_cells_by_fid(self, fault_id, bts_id=0):
        """
        Get cell ids affected by specific alarm fault id
        :param fault_id: alarm fault id
        :param bts_id: BTS id, default 0
        :return: set of cells ids
        """
        all_affected_cells = list()
        active_alarms = self.bts_alarm_obj.get_all_active_alarms(bts_id=bts_id)
        for alarm_item in active_alarms:
            if fault_id == alarm_item['faultId']:
                all_affected_cells.extend(self._get_affected_cells(full_alarm_message=alarm_item))
        return set(sorted(map(int, all_affected_cells)))

    def _wait_for_cell_initialization_end(self, cell_id, bts_id=0, timeout=120, interval=2):
        """
        Wait for cell reaches `initializing` state
        :param cell_id: cell idg
        :param bts_id: BTS id, default 0
        :param timeout: timeout for the operation, default 120s
        :param interval: wait additional time after failed execution, before next attempt, default 2s
        :return: None
        """
        start_time = time.time()
        end_time = start_time + time_to_seconds(time=timeout)
        interval_in_seconds = time_to_seconds(time=interval)
        while time.time() < end_time:
            try:
                self.bts_cell_obj.verify_cell_statuses(bts_id=bts_id, cell_id=cell_id, procedural_status='initializing',
                                                       availability_status='offline', cell_type='all')
                break
            except IncorrectStatuses as e1:
                logging.info(f'NRCELL-{cell_id} not in the initializing state: {repr(e1)}')
                time.sleep(interval_in_seconds)
        else:
            raise IncorrectStatuses(f'The timeout={timeout} has passed and CELL-{cell_id} '
                                    f'is still in the initializing state')

    @staticmethod
    def create_dict_with_parameter_to_verify(dist_name, parameter, value, bts_id=0, adjust_dist_name=True):
        """
        Create dictionary with parameter to verify
        :param dist_name: distName
        :param parameter: parameter name
        :param value: parameter value
        :param bts_id: BTS id, default 0
        :param adjust_dist_name: True if dist_name needs to be adjusted, default True
        :return: dict used for parameter verification
        """
        if adjust_dist_name:
            dist_name = GnbDuOperations().adjust_dist_name(dist_name=dist_name, bts_id=bts_id)
        return {dist_name: {parameter: value}}

    @staticmethod
    def verify_lane_dist_name_format(lane_dist_name):
        """
        Verify if lane distName is correct
        :param lane_dist_name: lane distName
        :return: tuple mod_dist_name, sfp_id, lane
        """
        pattern = re.compile(r'(?P<mod>.+/(BBMOD|SMOD)-\d+)/(?P<sfp>SFP-\d+)/(?P<lane>LANE-\d+)')
        matched = pattern.match(lane_dist_name)
        if not matched:
            raise ValueError(f'Wrong distName format for the LANE object: {lane_dist_name}')
        mod_dist_name = matched.group('mod')
        sfp_id = matched.group('sfp')
        lane = matched.group('lane')
        return mod_dist_name, sfp_id, lane

    @staticmethod
    def _get_affected_cells(full_alarm_message):
        """
        Retrieves from alarm message which cells are affected
        :param full_alarm_message: alarm message
        :return: cells ids
        """
        cells_ids = []
        for cell in full_alarm_message['impactedCellsList']:
            match = re.search(r'.*CEL+_R-(\d+)', cell, re.IGNORECASE)
            if match:
                cells_ids.append(match.group(1))
        return cells_ids

    @staticmethod
    def _get_proper_alarm_affecting_cells(lane_link_mode):
        """
        Returns alarm parameters depending on lane link mode
        :param lane_link_mode: lane link mode
        :return: alarm parameters
        """
        alarm_affecting_cells = {}
        if lane_link_mode["synchronization"] and (not lane_link_mode["configuration"]):
            alarm_affecting_cells = {
                'fault_id': 16,
                'fault_name': 'Unit synchronization fault'
            }
        elif lane_link_mode["configuration"]:
            alarm_affecting_cells = {
                'fault_id': 10,
                'fault_name': 'No connection to unit'
            }
        return alarm_affecting_cells


class GnbSFP(SFP):
    """Class contains SFP keywords for gNB"""

    bts_type = 'GNB'

    def __init__(self):
        """
        Constructor of Gnb class.

        """

        super(GnbSFP, self).__init__(bts_type=GnbSFP.bts_type)


class EnbSFP(SFP):
    """Class contains SFP keywords for eNB"""

    bts_type = 'ENB'

    def __init__(self):
        """
        Constructor of Enb class.

        """

        super(EnbSFP, self).__init__(bts_type=EnbSFP.bts_type)
